// Builds single-file.ts: logic.ts + handler.ts + index.ts in one file, for pasting into the
// Supabase dashboard editor (Edge Functions > Deploy a new function > Via Editor) when the CLI is not installed.
// Run: node supabase/functions/lemon-webhook/bundle.mjs
import { readFileSync, writeFileSync } from "node:fs";
const dir = new URL(".", import.meta.url);
const read = (f) => readFileSync(new URL(f, dir), "utf8");
const strip = (s) => s.split("\n").filter((l) => !/^import .* from "\.\/.*";$/.test(l)).join("\n").replace(/^export /gm, "");
const out = [
  "// GENERATED by bundle.mjs from logic.ts, handler.ts and index.ts. Edit those, then rebuild.",
  "// Paste this whole file into Supabase > Edge Functions > lemon-webhook > Code, and keep \"Verify JWT\" OFF.",
  strip(read("logic.ts")), strip(read("handler.ts")), strip(read("index.ts")),
].join("\n\n");
writeFileSync(new URL("single-file.ts", dir), out);
console.log("wrote single-file.ts", out.length, "bytes");
